"""ScanNet++-specific layout loading and feature extraction."""

from typing import Dict, Optional, Tuple

import numpy as np

from .front3d import (
    FRONT3D_FEATURE_TYPE_TO_INDEX,
    FRONT3D_NUM_SUBTYPE_CHANNELS,
    _category_to_subtype_index as _front3d_subtype,
    _encode_furniture_bbox,
    _encode_room_centroid,
    _encode_wall_segment,
    load_front3d_layout,
)
from .map_utils import FEATURE_DIM


SCANNETPP_NUM_SUBTYPE_CHANNELS = FRONT3D_NUM_SUBTYPE_CHANNELS

SCANNETPP_LAYOUT_TYPE_TO_FEATURE_INDEX = {
    0: FRONT3D_FEATURE_TYPE_TO_INDEX["wall_inner"],
    1: FRONT3D_FEATURE_TYPE_TO_INDEX["door"],
    2: FRONT3D_FEATURE_TYPE_TO_INDEX["window"],
}

SCANNETPP_CATEGORY_TO_SUBTYPE = {
    "chair": 0,
    "desk chair": 0,
    "office chair": 0,
    "office visitor chair": 0,
    "armchair": 0,
    "stool": 0,
    "bench": 0,
    "ottoman": 0,
    "beanbag": 0,
    "table": 1,
    "desk": 1,
    "bed": 2,
    "sofa": 3,
    "cabinet": 4,
    "shelf": 5,
    "bookshelf": 5,
    "light": 6,
    "lamp": 6,
    "tv": 7,
    "monitor": 7,
    "plant": 8,
}


def _scannetpp_subtype_index(raw_category: str) -> Optional[int]:
    return SCANNETPP_CATEGORY_TO_SUBTYPE.get(raw_category.strip().lower(), None)


def load_scannetpp_layout(layout_path: str, bbox_path: str) -> Dict:
    return load_front3d_layout(layout_path, bbox_path)


def get_local_scannetpp_features(
    layout_data: Dict,
    scene_shape: Tuple[int, int, int],
    bbox_min: np.ndarray,
    bbox_max: np.ndarray,
) -> np.ndarray:
    scene_z, scene_y, scene_x = scene_shape
    all_features = []

    wall_segments = layout_data["wall_segments"]
    wall_types = layout_data["wall_types"]
    polyline_ids = layout_data["polyline_ids"]

    chunk_x_min, chunk_x_max = float(bbox_min[2]), float(bbox_max[2])
    chunk_z_min, chunk_z_max = float(bbox_min[0]), float(bbox_max[0])

    if len(wall_segments) > 0:
        segs_vox = wall_segments.copy()
        segs_vox[:, :, 0] *= scene_x
        segs_vox[:, :, 1] *= scene_z
        for seg, wtype, pid in zip(segs_vox, wall_types, polyline_ids):
            p1, p2 = seg[0], seg[1]
            p1_in = (chunk_x_min <= p1[0] <= chunk_x_max) and (chunk_z_min <= p1[1] <= chunk_z_max)
            p2_in = (chunk_x_min <= p2[0] <= chunk_x_max) and (chunk_z_min <= p2[1] <= chunk_z_max)
            if not (p1_in or p2_in):
                continue
            feature_type_index = SCANNETPP_LAYOUT_TYPE_TO_FEATURE_INDEX.get(int(wtype))
            if feature_type_index is None:
                continue
            all_features.append(
                _encode_wall_segment(
                    np.array([p1[0] - chunk_x_min, p1[1] - chunk_z_min], dtype=np.float32),
                    np.array([p2[0] - chunk_x_min, p2[1] - chunk_z_min], dtype=np.float32),
                    feature_type_index,
                    int(pid),
                )
            )

    room_centroids = layout_data["room_centroids"]
    if len(room_centroids) > 0:
        cents_vox = room_centroids.copy()
        cents_vox[:, 0] *= scene_x
        cents_vox[:, 1] *= scene_z
        for cx, cz in cents_vox:
            if chunk_x_min <= cx <= chunk_x_max and chunk_z_min <= cz <= chunk_z_max:
                all_features.append(_encode_room_centroid(np.array([cx - chunk_x_min, cz - chunk_z_min], dtype=np.float32)))

    furniture_bboxes = layout_data["furniture_bboxes"]
    furniture_categories = layout_data["furniture_categories"]
    if len(furniture_bboxes) > 0:
        bboxes_vox = furniture_bboxes.copy()
        bboxes_vox[:, :, 0] *= scene_x
        bboxes_vox[:, :, 1] *= scene_y
        bboxes_vox[:, :, 2] *= scene_z
        chunk_y_min, chunk_y_max = float(bbox_min[1]), float(bbox_max[1])
        for bbox, cat in zip(bboxes_vox, furniture_categories):
            box_min, box_max = bbox[0], bbox[1]
            bx_min, by_min, bz_min = box_min
            bx_max, by_max, bz_max = box_max
            if bx_max < chunk_x_min or bx_min > chunk_x_max:
                continue
            if by_max < chunk_y_min or by_min > chunk_y_max:
                continue
            if bz_max < chunk_z_min or bz_min > chunk_z_max:
                continue
            subtype_idx = _scannetpp_subtype_index(cat)
            if subtype_idx is None:
                subtype_idx = _front3d_subtype(cat)
            center_xzy = np.array([
                (bx_min + bx_max) / 2.0 - chunk_x_min,
                (by_min + by_max) / 2.0 - chunk_y_min,
                (bz_min + bz_max) / 2.0 - chunk_z_min,
            ], dtype=np.float32)
            half_extents_xzy = np.array([
                (bx_max - bx_min) / 2.0,
                (by_max - by_min) / 2.0,
                (bz_max - bz_min) / 2.0,
            ], dtype=np.float32)
            all_features.append(_encode_furniture_bbox(center_xzy, half_extents_xzy, subtype_idx))

    if not all_features:
        return np.zeros((0, FEATURE_DIM), dtype=np.float32)
    return np.concatenate(all_features, axis=0)
